                            let summary = '';
                            await this.aiGateway.streamCompletionWithContext([{ role: 'user', content: `Summarize the KEY FINDINGS from this research in 800-1200 words. Retain all specific data, numbers, sources (URLs) and recommendations. CRITICAL: Retain ALL images in ![description](url) format — do not delete or change URLs. Do NOT lose any specific fact.\n\n${output}` }], { tenantId, userId, conversationId: convId, businessContext: bizContext, useFallback: true }, (chunk) => { summary += chunk; });
                            agentParts.push(`### ${job.agentType.toUpperCase()} research (summarized)\n${summary}`);
                            this.logger.log({ message: `Headless: summarized ${job.agentType} output`, taskId, original: output.length, summarized: summary.length });
